H.background();
const g = 9.8, v0 = Math.max(1, P.v0), deg = P.deg;
const ang = deg * Math.PI / 180;
const vx = v0 * Math.cos(ang), vy0 = v0 * Math.sin(ang);
const tFlight = Math.max(0.2, 2 * vy0 / g);
const range = vx * tFlight;
const hMax = (vy0 * vy0) / (2 * g);
const v = H.plot2d({ xMin: 0, xMax: Math.max(8, range * 1.15), yMin: 0, yMax: Math.max(4, hMax * 1.3) });
v.grid(); v.axes();
const xf = (tt) => vx * tt;
const yf = (tt) => vy0 * tt - 0.5 * g * tt * tt;
const pts = [];
for (let i = 0; i <= 80; i++) { const tt = tFlight * i / 80; pts.push([xf(tt), Math.max(0, yf(tt))]); }
v.path(pts, { color: H.colors.accent, width: 3 });
const tApex = vy0 / g;
v.dot(xf(tApex), hMax, { r: 5, fill: H.colors.yellow });
const tt = (t % (tFlight + 0.5));
const cx = xf(Math.min(tt, tFlight)), cy = Math.max(0, yf(Math.min(tt, tFlight)));
const cvy = vy0 - g * Math.min(tt, tFlight);
v.dot(cx, cy, { r: 6, fill: H.colors.warn });
v.arrow(cx, cy, cx + vx * 0.12, cy, { color: H.colors.good, width: 2 });
v.arrow(cx, cy, cx, cy + cvy * 0.12, { color: H.colors.violet, width: 2 });
H.text("Angled launch:  R = v0^2 sin(2*theta) / g", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("v0 = " + v0.toFixed(1) + " m/s   theta = " + deg.toFixed(0) + " deg   range = " + range.toFixed(2) + " m   apex = " + hMax.toFixed(2) + " m", 24, 52, { color: H.colors.sub, size: 12 });
H.legend([{ label: "vx", color: H.colors.good }, { label: "vy", color: H.colors.violet }, { label: "apex", color: H.colors.yellow }], H.W - 130, 28);
